SELECT COUNT(*) INTO n FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='doors' AND ENGINE='InnoDB';
IF n<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Court engine drift: doors'; END IF;
SELECT COUNT(*) INTO n FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='doors';
