dest_heading` AS CHAR) <=> BINARY CONVERT(X'30' USING utf8mb4) AND BINARY CAST(`invert_state` AS CHAR) <=> BINARY CONVERT(X'30' USING utf8mb4) AND BINARY CAST(`incline` AS CHAR) <=> BINARY CONVERT(X'30' USING utf8mb4) AND BINARY CAST(`size` AS CHAR) <=> BINARY CONVERT(X'313430' USING utf8mb4) AND BINARY CAST(`buffer` AS CHAR) <=> BINARY CONVERT(X'30' USING utf8mb4) AND BINARY CAST(`client_version_mask` AS CHAR) <=> BINARY CONVERT(X'34323934393637323935' USING utf8mb4) AND BINARY CAST(`is_ldon_door` AS CHAR) <=> BINARY CONVERT(X'30' USING utf8mb4) AND BINARY CAST(`close_timer_ms` AS CHAR) <=> BINARY CONVERT(X'35303030' USING utf8mb4) AND BINARY CAST(`dz_switch_id` AS CHAR) <=> BINARY CONVERT(X'30' USING utf8mb4) AND BINARY CAST(`min_expansion` AS CHAR) <=> BINARY CONVERT(X'2d31' USING utf8mb4) AND BINARY CAST(`max_expansion` AS CHAR) <=> BINARY CONVERT(X'2d31' USING utf8mb4) AND BINARY CAST(`content_flags` AS CHAR) <=> BINARY NULL AND BINARY CAST(`content_flags_disabled` AS CHAR) <=> BINARY NULL;
